  "content": """"Deterministic local graders shared by every item family.

All graders take the candidate's raw reply text and return either a float in
[0,1] or a dict accepted by research_sdk.Client.item.  No grader inspects the
candidate identity, and none of them looks at reference-benchmark labels.
"""
import json
import os
import re
import subprocess
import sys
import tempfile

# ---------------------------------------------------------------- text utils

CODE_RE = re.compile(r"```(?:python|py)?\s*\n(.*?)```", re.S)


def extract_code(text):
    """Last fenced block wins; fall back to the whole reply."""
    blocks = CODE_RE.findall(text)
    if blocks:
        return max(blocks, key=len)
    return text


def extract_tagged(text, tag="ANSWER"):
    """Return the content after the final `TAG:` marker (or boxed{} / last line)."""
    pat = re.compile(r"(?:\*\*)?" + tag + r"(?:\*\*)?\s*[:\-]?\s*(.+)", re.I)
    hits = pat.findall(text)
    if hits:
        return hits[-1].strip()
    boxed = find_boxed(text)
    if boxed is not None:
        return boxed
    lines = [l.strip() for l in text.strip().splitlines() if l.strip()]
    return lines[-1] if lines else ""


def find_boxed(text):
    idx = text.rfind("\\boxed")
    if idx < 0:
        return None
    i = text.find("{", idx)
    if i < 0:
        return None
    depth, out = 0, []
    for ch in text[i:]:
        if ch == "{":
            depth += 1
            if depth == 1:
                continue
        elif ch == "}":
            depth -= 1
            if depth == 0:
                break
        out.append(ch)
    return "".join(out).strip()


_NORM_DROP = re.compile(r"[\s\$\\,]+")


def norm_answer(s):
    """Aggressive canonicalisation for short exact-match answers."""
    if s is None:
        return ""
    s = s.strip()
    s = re.sub(r"^\**|\**$", "", s).strip()
    s = s.replace("\\left", "").replace("\\right", "")
    s = s.replace("\\!", "").replace("\\;", "").replace("\\,", "")
    s = s.replace("\\dfrac", "\\frac").replace("\\tfrac", "\\frac")
    s = s.replace("^{\\circ}", "").replace("^\\circ", "")
    s = re.sub(r"\\text\{([^}]*)\}", r"\1", s)
    s = re.sub(r"\\mathbb\{([^}]*)\}", r"\1", s)
    s = re.sub(r"\\mathrm\{([^}]*)\}", r"\1", s)
    s = s.rstrip(".")
    s = s.lower()
    s = _NORM_DROP.sub("", s)
    s = s.replace("{", "").replace("}", "").replace("(", "").replace(")", "")
    return s


def numeric_value(s):
    s = s.replace(",", "").replace("$", "").strip()
    m = re.fullmatch(r"[-+]?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?%?", s)
    if not m:
        return None
    try:
        return float(s.rstrip("%"))
    except ValueError:
        return None


def exact_match(text, gold, aliases=(), tag="ANSWER"):
    got = extract_tagged(text, tag)
    cands = [gold, *aliases]
    g = norm_answer(got)
    if g == "":
        return {"score": 0.0, "answer_status": "invalid"}
    for c in cands:
        if g == norm_answer(c):
            return {"score": 1.0, "answer_status": "answered"}
    gv, = (numeric_value(got),)
    if gv is not None:
        for c in cands:
            cv = numeric_value(str(c))
            if cv is not None and abs(gv - cv) <= 1e-6 * max(1.0, abs(cv)):
                return {"score": 1.0, "answer_status": "answered"}
    return {"score": 0.0, "answer_status": "answered"}


def mc_match(text, gold):
    got = extract_tagged(text)
    m = re.search(r"\b([A-J])\b", got.upper())
    letter = m.group(1) if m else norm_answer(got).upper()[:1]
    return {"score": 1.0 if letter == gold.strip().upper()[:1] else 0.0,
            "answer_status": "answered" if letter else "invalid"}


# ------------------------------------------------------------- code sandbox

HARNESS = '''
import json, sys, math
RESULTS = {}
def _run(name, fn):
    try:
        fn()
        RESULTS[name] = 1
    except BaseException:
        RESULTS[name] = 0
try:
    exec(compile(open(sys.argv[1]).read(), "candidate.py", "exec"), globals())
except BaseException:
    print("__RESULTS__" + json.dumps({}))
    raise SystemExit(0)
{TESTS}
print("__RESULTS__" + json.dumps(RESULTS))
'''


def run_code_tests(code, tests, timeout=30):
    """tests: list of python snippets; each must raise on failure.

    Returns (fraction_passed, detail dict).  A candidate file that fails to
    import scores 0 on every test.
    """
    body = []
    for i, snip in enumerate(tests):
        indented = "\n".join("    " + l for l in snip.strip("\n").splitlines())
        body.append("def _t%d():\n%s\n_run('t%d', _t%d)" % (i, indented, i, i))
    prog = HARNESS.replace("{TESTS}", "\n".join(body))
    with tempfile.TemporaryDirectory() as d:
        cand = os.path.join(d, "candidate.py")
        harn = os.path.join(d, "harness.py")
        open(cand, "w").write(code)
        open(harn, "w").write(prog)
        try:
            p = subprocess.run([sys.executable, harn, cand], cwd=d, timeout=timeout,
                               capture_output=True, text=True)
            out = p.stdout
        except subprocess.TimeoutExpired:
            return 0.0, {"error": "timeout"}
        except Exception as exc:                      # pragma: no cover
            return 0.0, {"error": repr(exc)}
    m = re.search(r"__RESULTS__(\{.*\})", out)
    if not m:
        return 0.0, {"error": "no-results", "stdout": out[-400:]}
    res = json.loads(m.group(1))
    if not tests:
        return 0.0, {}
    return sum(res.get("t%d" % i, 0) for i in range(len(tests))) / len(tests), res


def code_grader(tests, timeout=30):
    def grade(text):
        code = extract_code(text)
        if not code.strip():
            return {"score": 0.0, "answer_status": "invalid"}
        frac, detail = run_code_tests(code, tests, timeout)
        return {"score": round(frac, 6), "answer_status": "answered", "detail": detail}
    return grade


# ------------------------------------------------- constraint-checklist grader

def checklist_grader(checks):
    """checks: list of (name, callable(text) -> bool).  Score = fraction true."""
    def grade(text):
        passed, names = 0, {}
        for name, fn in checks:
            try:
                ok = bool(fn(text))
            except Exception:
                ok = False
            names[name] = int(ok)
            passed += int(ok)
        return {"score": round(passed / len(checks), 6), "answer_status": "answered",
                "detail": names}
    return grade
